package com.tuowei.erp.masterdata.supplierproduct.controller;
import com.tuowei.erp.common.security.PermissionCodes; import com.tuowei.erp.common.web.ApiResponse; import com.tuowei.erp.masterdata.supplierproduct.service.SupplierProductRelationService; import com.tuowei.erp.masterdata.supplierproduct.web.SupplierProductRelationRequest; import com.tuowei.erp.masterdata.supplierproduct.web.SupplierProductRelationResponse; import jakarta.validation.Valid; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.List;
@RestController @RequestMapping("/api/masterdata/suppliers/{supplierId}/products") public class SupplierProductRelationController { private final SupplierProductRelationService service; public SupplierProductRelationController(SupplierProductRelationService service){this.service=service;} @PreAuthorize(PermissionCodes.HAS_MASTERDATA_SUPPLIER_VIEW) @GetMapping public ApiResponse<List<SupplierProductRelationResponse>> list(@PathVariable Long supplierId){return ApiResponse.success(service.list(supplierId));} @PreAuthorize(PermissionCodes.HAS_MASTERDATA_SUPPLIER_UPDATE) @PostMapping public ApiResponse<SupplierProductRelationResponse> save(@PathVariable Long supplierId,@Valid @RequestBody SupplierProductRelationRequest request){return ApiResponse.success(service.save(supplierId,request));} @PreAuthorize(PermissionCodes.HAS_MASTERDATA_SUPPLIER_UPDATE) @DeleteMapping("/{id}") public ApiResponse<Void> delete(@PathVariable Long supplierId,@PathVariable Long id){service.delete(supplierId,id);return ApiResponse.success(null);} }
